SELECT
    'snapshot_1' AS snap,
    ROUND(MIN(pos_y)::numeric,4) AS min_lat, ROUND(MAX(pos_y)::numeric,4) AS max_lat,
    ROUND(MIN(pos_x)::numeric,4) AS min_lon, ROUND(MAX(pos_x)::numeric,4) AS max_lon,
    COUNT(*) AS vehicles
FROM "references".wialon_units_snapshot_1
UNION ALL
SELECT 'snapshot_2', ROUND(MIN(pos_y)::numeric,4), ROUND(MAX(pos_y)::numeric,4),
